DROP TABLE IF EXISTS `screentimes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `screentimes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) DEFAULT NULL,
  `format` varchar(100) DEFAULT NULL,
  `time` time DEFAULT NULL,
  `date` datetime DEFAULT NULL,
  `language` varchar(100) DEFAULT NULL,
  `standard_price` varchar(10) DEFAULT NULL,
  `vip_price` varchar(10) DEFAULT NULL,
  `other_price` varchar(10) DEFAULT NULL,
  `booking_url` text,
  `cinema_id` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `film_id` varchar(200) DEFAULT NULL COMMENT 'Link to specific film',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=614 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
